REPLACE INTO `soal` VALUES (17,'LAT-R-001',2,'latihan','rendah','notasi_konsep_komposisi','Menentukan fungsi invers, komposisi fungsi, dan transformasi fungsi untuk memodelkan situasi dunia nyata menggunakan fungsi yang sesuai (linear, kuadrat, eksponensial).','Menentukan komposisi dua fungsi atau lebih serta menjelaskan urutan dan sifat yang berlaku pada komposisi fungsi.','TP02','IPK2.1','C2','Latihan tingkat rendah. Diberikan f(x)=3x+2 dan g(x)=x+2. Bentuk (f o g)(x) menyatakan ...','f(g(x))','g(f(x))','f(x)+g(x)','f(x)g(x)','f(x)-g(x)','a','Pada f o g, fungsi g dikerjakan lebih dahulu dan hasilnya menjadi masukan fungsi f.','{\"tp\": \"TP02\", \"ipk\": \"IPK2.1\", \"kind\": \"literal\", \"expected\": \"f(g(x))\", \"template\": \"composition_notation_two\", \"cognitive\": \"C2\"}',1),(18,'LAT-R-002',2,'latihan','rendah','notasi_konsep_komposisi','Menentukan fungsi invers, komposisi fungsi, dan transformasi fungsi untuk memodelkan situasi dunia nyata menggunakan fungsi yang sesuai (linear, kuadrat, eksponensial).','Menentukan komposisi dua fungsi atau lebih serta menjelaskan urutan dan sifat yang berlaku pada komposisi fungsi.','TP02','IPK2.1','C2','Latihan tingkat rendah. Diberikan f(x)=4x+3 dan g(x)=x+3. Bentuk (f o g)(x) menyatakan ...','f(x)-g(x)','f(g(x))','g(f(x))','f(x)+g(x)','f(x)g(x)','b','Pada f o g, fungsi g dikerjakan lebih dahulu dan hasilnya menjadi masukan fungsi f.','{\"tp\": \"TP02\", \"ipk\": \"IPK2.1\", \"kind\": \"literal\", \"expected\": \"f(g(x))\", \"template\": \"composition_notation_two\", \"cognitive\": \"C2\"}',1),(19,'LAT-R-003',2,'latihan','rendah','notasi_konsep_komposisi','Menentukan fungsi invers, komposisi fungsi, dan transformasi fungsi untuk memodelkan situasi dunia nyata menggunakan fungsi yang sesuai (linear, kuadrat, eksponensial).','Menentukan komposisi dua fungsi atau lebih serta menjelaskan urutan dan sifat yang berlaku pada komposisi fungsi.','TP02','IPK2.1','C2','Latihan tingkat rendah. Diberikan f(x)=5x+4 dan g(x)=x+4. Bentuk (f o g)(x) menyatakan ...','f(x)g(x)','f(x)-g(x)','f(g(x))','g(f(x))','f(x)+g(x)','c','Pada f o g, fungsi g dikerjakan lebih dahulu dan hasilnya menjadi masukan fungsi f.','{\"tp\": \"TP02\", \"ipk\": \"IPK2.1\", \"kind\": \"literal\", \"expected\": \"f(g(x))\", \"template\": \"composition_notation_two\", \"cognitive\": \"C2\"}',1),(20,'LAT-R-004',2,'latihan','rendah','notasi_konsep_komposisi','Menentukan fungsi invers, komposisi fungsi, dan transformasi fungsi untuk memodelkan situasi dunia nyata menggunakan fungsi yang sesuai (linear, kuadrat, eksponensial).','Menentukan komposisi dua fungsi atau lebih serta menjelaskan urutan dan sifat yang berlaku pada komposisi fungsi.','TP02','IPK2.1','C2','Latihan tingkat rendah. Diberikan f(x)=6x+5 dan g(x)=x+5. Bentuk (f o g)(x) menyatakan ...','f(x)+g(x)','f(x)g(x)','f(x)-g(x)','f(g(x))','g(f(x))','d','Pada f o g, fungsi g dikerjakan lebih dahulu dan hasilnya menjadi masukan fungsi f.','{\"tp\": \"TP02\", \"ipk\": \"IPK2.1\", \"kind\": \"literal\", \"expected\": \"f(g(x))\", \"template\": \"composition_notation_two\", \"cognitive\": \"C2\"}',1),(21,'LAT-R-005',2,'latihan','rendah','notasi_konsep_komposisi','Menentukan fungsi invers, komposisi fungsi, dan transformasi fungsi untuk memodelkan situasi dunia nyata menggunakan fungsi yang sesuai (linear, kuadrat, eksponensial).','Menentukan komposisi dua fungsi atau lebih serta menjelaskan urutan dan sifat yang berlaku pada komposisi fungsi.','TP02','IPK2.1','C2','Latihan tingkat rendah. Diberikan f(x)=7x+6 dan g(x)=x+6. Bentuk (f o g)(x) menyatakan ...','g(f(x))','f(x)+g(x)','f(x)g(x)','f(x)-g(x)','f(g(x))','e','Pada f o g, fungsi g dikerjakan lebih dahulu dan hasilnya menjadi masukan fungsi f.','{\"tp\": \"TP02\", \"ipk\": \"IPK2.1\", \"kind\": \"literal\", \"expected\": \"f(g(x))\", \"template\": \"composition_notation_two\", \"cognitive\": \"C2\"}',1),(22,'LAT-R-006',2,'latihan','rendah','notasi_konsep_komposisi','Menentukan fungsi invers, komposisi fungsi, dan transf